package ru.arc.paper.actionpanel

import org.bukkit.Chunk
import org.bukkit.FluidCollisionMode
import org.bukkit.Location
import org.bukkit.block.Block
import org.bukkit.entity.Player
import org.bukkit.util.Vector
import kotlin.math.ceil
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min

/** Exact primary-thread world boundary. No chunks are loaded or generated by a panel query. */
internal class ActionPanelWorldSpace {
    fun safe(
        player: Player,
        eye: ActionPanelPoint,
        anchor: ActionPanelAnchor,
        rectangles: List<ActionPanelRect>,
        reach: Double,
        clearance: Double,
        lineOfSight: Boolean,
        blocksRay: (Block) -> Boolean,
    ): Boolean {
        if (rectangles.isEmpty()) return false
        if (!ActionPanelGeometry.allReachable(eye, anchor, rectangles, reach)) return false
        val volume = ActionPanelGeometry.volume(anchor, rectangles, ActionPanelGeometry.SURFACE_CLEARANCE + clearance)
        if (!spaceClear(player, ActionPanelGeometry.bounds(volume)) { ActionPanelGeometry.overlaps(volume, it) }) return false
        if (!lineOfSight) return true
        return rectangles.flatMap { ActionPanelGeometry.corners(anchor, it) }.distinct().all { target ->
            rayClear(player, eye, target, 0.025, blocksRay)
        }
    }

    fun clearSweep(player: Player, bounds: ActionPanelBounds): Boolean = spaceClear(player, bounds, bounds::overlaps)

    private fun spaceClear(player: Player, bounds: ActionPanelBounds, overlaps: (ActionPanelBounds) -> Boolean): Boolean {
        val world = player.world
        if (bounds.minY < world.minHeight || bounds.maxY >= world.maxHeight) return false
        val minX = floor(bounds.minX + EPSILON).toInt()
        val maxX = max(minX, ceil(bounds.maxX - EPSILON).toInt() - 1)
        val minY = floor(bounds.minY + EPSILON).toInt()
        val maxY = max(minY, ceil(bounds.maxY - EPSILON).toInt() - 1)
        val minZ = floor(bounds.minZ + EPSILON).toInt()
        val maxZ = max(minZ, ceil(bounds.maxZ - EPSILON).toInt() - 1)
        for (x in (minX shr 4)..(maxX shr 4)) for (z in (minZ shr 4)..(maxZ shr 4)) {
            if (!knownChunk(player, x, z)) return false
        }
        for (x in minX..maxX) for (y in minY..maxY) for (z in minZ..maxZ) {
            val block = world.getBlockAt(x, y, z)
            if (block.collisionShape.boundingBoxes.any { box -> overlaps(ActionPanelBounds(
                    x + box.minX, y + box.minY, z + box.minZ, x + box.maxX, y + box.maxY, z + box.maxZ,
                )) }) return false
        }
        return true
    }

    fun rayClear(player: Player, from: ActionPanelPoint, to: ActionPanelPoint, blocksRay: (Block) -> Boolean): Boolean {
        return rayClear(player, from, to, 0.0, blocksRay)
    }

    private fun rayClear(player: Player, from: ActionPanelPoint, to: ActionPanelPoint, endInset: Double, blocksRay: (Block) -> Boolean): Boolean {
        val distance = ActionPanelGeometry.distance(from, to)
        if (distance <= EPSILON || !knownRayChunks(player, from, to)) return false
        val origin = Location(player.world, from.x, from.y, from.z)
        val direction = Vector(to.x - from.x, to.y - from.y, to.z - from.z).normalize()
        return player.world.rayTraceBlocks(origin, direction, max(0.0, distance - endInset),
            FluidCollisionMode.NEVER, true, blocksRay) == null
    }

    private fun knownRayChunks(player: Player, from: ActionPanelPoint, to: ActionPanelPoint): Boolean {
        for (x in (floor(min(from.x, to.x)).toInt() shr 4)..(floor(max(from.x, to.x)).toInt() shr 4)) {
            for (z in (floor(min(from.z, to.z)).toInt() shr 4)..(floor(max(from.z, to.z)).toInt() shr 4)) {
                if (!knownChunk(player, x, z)) return false
            }
        }
        return true
    }

    private fun knownChunk(player: Player, x: Int, z: Int): Boolean =
        player.world.isChunkLoaded(x, z) && player.isChunkSent(Chunk.getChunkKey(x, z))

    private companion object { const val EPSILON = 1e-5 }
}
